import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";
import type { IPageIUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIUser";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IUserRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IUserRole";

/**
 * E2E test for paginated and filterable user listing (core.users PATCH).
 *
 * Validates:
 * 1. Default fetch with no parameters: page=1/limit=100.
 * 2. Filtering by search (email, username) with and without case sensitivity.
 * 3. Filtering by a valid user role UUID.
 * 4. Behavior when requesting a page well beyond available pages.
 * 5. Pagination metadata: correct current/limit/pages/records.
 *
 * Business context: Board administrators need reliable, predictable ways to
 * fetch, filter, and paginate large user lists to manage moderation, audit
 * activity, or find profiles quickly. This ensures both proper security (role
 * filtering only allowed for authorized users) and smooth frontend UX.
 *
 * 1. Fetch with default params – verify structure, default limit, ordering.
 * 2. Use email/username fragment in 'search' param (get at least one result; check it matches filter).
 * 3. Find (or create, if needed) a user role and filter list by that role; verify only users of that role returned.
 * 4. Request an out-of-bounds page (e.g., page=1000000) and check for proper error/empty data.
 */
export async function test_api_core_test_list_users_with_pagination_and_filtering(
  connection: api.IConnection,
) {
  // 1. Fetch user list with default settings
  const resultDefault = await api.functional.core.users.patch(connection, {body: {}});
  typia.assert(resultDefault);
  TestValidator.equals("current page is 1")(1)(resultDefault.pagination.current);
  TestValidator.equals("default limit is 100")(100)(resultDefault.pagination.limit);
  // Should sort/order by username or id ascending (default); verify sorted order (if list not empty)
  if (resultDefault.data.length > 1)
    for (let i = 1; i < resultDefault.data.length; ++i)
      TestValidator.predicate("default order ascending")(
        resultDefault.data[i-1].username <= resultDefault.data[i].username
      );

  // 2. Use a fragment of a known user's email or username as 'search'
  const knownUser = resultDefault.data[0];
  if (knownUser) {
    const searchFragment = knownUser.username.slice(0, 2); // Take first 2 chars of username
    const resultSearch = await api.functional.core.users.patch(connection, {body: {search: searchFragment}});
    typia.assert(resultSearch);
    // Every result should contain the fragment in username or email (case-insensitive)
    for (const user of resultSearch.data) {
      TestValidator.predicate('username/email includes fragment')(
        user.username.toLowerCase().includes(searchFragment.toLowerCase()) ||
        (user as any).email?.toLowerCase().includes(searchFragment.toLowerCase())
      );
    }
  }

  // 3. Filtering by role: pick a role from a user (if any), then filter for that role
  if (resultDefault.data.length > 0) {
    const knownRole = resultDefault.data[0].role;
    const resultFilter = await api.functional.core.users.patch(connection, {body: {role: knownRole.id}});
    typia.assert(resultFilter);
    for (const user of resultFilter.data) {
      TestValidator.equals('all users have requested role')(knownRole.id)(user.role.id);
    }
  }

  // 4. Out-of-range pagination: request page 1000000
  const resultOver = await api.functional.core.users.patch(connection, {body: {page: 1000000}});
  typia.assert(resultOver);
  // Data should be empty if page is out of range (unless user db actually huge)
  TestValidator.equals("page 1000000 should be empty[]")(0)(resultOver.data.length);
}

