import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";
import type { IUserRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IUserRole";
import type { IPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IVote";

/**
 * Validate getting a user profile by ID (success and error cases)
 *
 * 1. Create a real user account via POST /core/users
 * 2. Retrieve created user's profile via GET /core/users/{id} (should succeed, validate all fields)
 * 3. Try GET with a random (nonexistent) UUID (should return 404)
 * 4. (If applicable) Try GET with another account/permissions to check for access denied (should error if not permitted)
 */
export async function test_api_core_test_get_user_profile_by_id_success_and_failure(
  connection: api.IConnection,
) {
  // 1. Create a new user
  const roleId = typia.random<string & tags.Format<"uuid">>();
  const createInput: IUser.ICreate = {
    user_role_id: roleId,
    username: RandomGenerator.alphaNumeric(10),
    email: typia.random<string & tags.Format<"email">>(),
    bio: "E2E test bio",
    password: "P4ssw0rd!e2e",
    status: "active",
  };
  const created: IUser = await api.functional.core.users.post(connection, { body: createInput });
  typia.assert(created);

  // 2. Retrieve the user profile with correct ID (should succeed)
  const found: IUser = await api.functional.core.users.getById(connection, { id: created.id });
  typia.assert(found);
  TestValidator.equals("user.id")(created.id)(found.id);
  TestValidator.equals("user.username")(created.username)(found.username);
  TestValidator.equals("user.email")(created.email)(found.email);
  TestValidator.equals("user.status")(created.status)(found.status);

  // 3. Try with a non-existent user ID (should error 404)
  await TestValidator.error("not found")(() =>
    api.functional.core.users.getById(connection, { id: typia.random<string & tags.Format<"uuid">>() }),
  );

  // 4. (If access control) Try as another or unauthorized user (implementation only if system supports roles and blocks private access; if not, skip or document)
}

