/**
 * Validate getting a user profile by ID (success and error cases)
 *
 * 1. Create a new user via POST /core/users (with a random but valid role ID, username, email, password, status)
 * 2. Retrieve that user by GET /core/users/{id}; validate returned fields match what was created
 * 3. Request with a random non-existent UUID as ID; confirm a 404 error is thrown
 * 4. (Optional/if access controlled) Attempt as a different/unauthorized user to check rejection—skipped if unnecessary
 */
export async function test_api_core_test_get_user_profile_by_id_success_and_failure(
  connection: api.IConnection,
) {
  // 1. Create a new user account with unique username/email
  const roleId = typia.random<string & tags.Format<"uuid">>();
  const createInput: IUser.ICreate = {
    user_role_id: roleId,
    username: RandomGenerator.alphaNumeric(10),
    email: typia.random<string & tags.Format<"email">>(),
    bio: "E2E test bio",
    password: "P4ssw0rd!e2e",
    status: "active",
  };
  const created: IUser = await api.functional.core.users.post(connection, { body: createInput });
  typia.assert(created);

  // 2. Retrieve by ID (should succeed and match what was created)
  const found: IUser = await api.functional.core.users.getById(connection, { id: created.id });
  typia.assert(found);
  TestValidator.equals("id")(created.id)(found.id);
  TestValidator.equals("username")(created.username)(found.username);
  TestValidator.equals("email")(created.email)(found.email);
  TestValidator.equals("status")(created.status)(found.status);
  if (created.bio !== undefined && created.bio !== null)
    TestValidator.equals("bio")(created.bio)(found.bio);

  // 3. Retrieve with a non-existent id (should result in error/404)
  await TestValidator.error("not found")(() =>
    api.functional.core.users.getById(connection, { id: typia.random<string & tags.Format<"uuid">>() }),
  );

  // 4. (If access control: try as other/unauthorized user if the system blocks private profile; if not supported, skip)
}

