import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IVote";

/**
 * E2E test for user registration including uniqueness and required fields validation.
 *
 * This test validates:
 * 1. Registration of a user with valid, unique data.
 * 2. Enforcement of unique constraints (email and username).
 * 3. Error handling when attempting to register with an existing email/username.
 * 4. Validation of required field enforcement by attempting to omit them.
 *
 * Workflow steps:
 * 1. Register a new user with valid, unique data for all required fields. Assert that a user is created and returned data matches constraints.
 * 2. Attempt to register another user with the *same* email and expect a unique constraint error.
 * 3. Attempt to register another user with the *same* username and expect a unique constraint error.
 * 4. Attempt to register a user omitting each required field (username, email, password, status, user_role_id) one by one, and assert the proper validation error is returned (skip if TypeScript-level omission causes compile error).
 *
 * Only business-logic errors should be tested – skip compilation errors that cannot occur at runtime.
 */
export async function test_api_core_test_register_user_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Register a valid user
  const newEmail = typia.random<string & tags.Format<"email">>();
  const newUsername = RandomGenerator.alphaNumeric(10);
  const newPassword = RandomGenerator.alphaNumeric(12);
  const userRoleId = typia.random<string & tags.Format<"uuid">>();
  const status = "active";
  const user1 = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: userRoleId,
      username: newUsername,
      email: newEmail,
      password: newPassword,
      status,
    } satisfies IUser.ICreate,
  });
  typia.assert(user1);
  TestValidator.equals("username")(newUsername)(user1.username);
  TestValidator.equals("email")(newEmail)(user1.email);
  TestValidator.equals("status")(status)(user1.status);

  // 2. Attempt duplicate email
  await TestValidator.error("duplicate email should fail")(async () => {
    return api.functional.core.users.post(connection, {
      body: {
        user_role_id: typia.random<string & tags.Format<"uuid">>(),
        username: RandomGenerator.alphaNumeric(10),
        email: newEmail,
        password: RandomGenerator.alphaNumeric(12),
        status: "active",
      } satisfies IUser.ICreate,
    });
  });

  // 3. Attempt duplicate username
  await TestValidator.error("duplicate username should fail")(async () => {
    return api.functional.core.users.post(connection, {
      body: {
        user_role_id: typia.random<string & tags.Format<"uuid">>(),
        username: newUsername,
        email: typia.random<string & tags.Format<"email">>(),
        password: RandomGenerator.alphaNumeric(12),
        status: "active",
      } satisfies IUser.ICreate,
    });
  });

  // 4. Required field omission tests
  // (All required field omissions at compile-time cannot be tested in valid TypeScript; skip these cases as instructed.)
}

