  const newEmail = typia.random<string & tags.Format<"email">>();
  const newUsername = RandomGenerator.alphaNumeric(10);
  const newPassword = RandomGenerator.alphaNumeric(12);
  const userRoleId = typia.random<string & tags.Format<"uuid">>();
  const status = "active";
  const user1 = await api.functional.core.users.post(connection, {
    body: {
