import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";
import type { IUserRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IUserRole";
import type { IPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IVote";

/**
 * E2E test: Update user profile and validate correct and incorrect update paths.
 *
 * Business context:
 * - Users may update their own profile details (bio, username, email, etc.).
 * - Certain fields such as 'id' and 'created_at' are immutable and cannot be changed.
 * - User update must enforce unique constraints on username/email.
 * - If trying to update a user that does not exist, API must return 404.
 *
 * Test process:
 * 1. Create a valid user.
 * 2. Update user profile with valid field changes (e.g., username, email, bio, status). Assert fields are updated and timestamps are refreshed.
 * 3. Attempt to update immutable/restricted fields ('id', 'created_at'); expect API rejection (error or ignored update).
 * 4. Try updating with a duplicate username/email (should fail with unique constraint error).
 * 5. Attempt update on non-existent user (random UUID); expect 404 error.
 */
export async function test_api_core_test_update_user_profile_success_and_failure(
  connection: api.IConnection,
) {
  // 1. Create a valid user
  const user: IUser = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: ...,
      username: ...,
      email: ...,
      bio: ...,
      password: ...,
      status: ...,
    } satisfies IUser.ICreate,
  });
  typia.assert(user);

  // 2. Update with valid changes
  const updateResult: IUser = await api.functional.core.users.putById(connection, {
    id: user.id,
    body: {
      username: ..., // new unique username
      email: ...,    // new unique email
      bio: ...,      // modified bio
      status: ...,   // maybe change status
    } satisfies IUser.IUpdate,
  });
  typia.assert(updateResult);
  TestValidator.equals("updated username")(updateResult.username)(...);
  TestValidator.equals("updated email")(updateResult.email)(...);

  // 3. Attempt to update immutable fields (should reject or ignore)
  await TestValidator.error("cannot change immutable fields")(() =>
    api.functional.core.users.putById(connection, {
      id: user.id,
      body: {
        id: typia.random<string & tags.Format<"uuid">>(), // Not allowed
        created_at: new Date().toISOString(), // Not allowed
      } as any,
    })
  );

  // 4. Duplicate username/email update attempt
  const otherUser: IUser = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: ...,
      username: ..., // known unique
      email: ...,    // known unique
      password: ...,
      status: ...,
    } satisfies IUser.ICreate,
  });

  await TestValidator.error("unique constraint")(() =>
    api.functional.core.users.putById(connection, {
      id: otherUser.id,
      body: {
        username: updateResult.username, // duplicate username
        email: updateResult.email,       // duplicate email
      } satisfies IUser.IUpdate,
    })
  );

  // 5. Update non-existent user
  await TestValidator.error("404 not found")(() =>
    api.functional.core.users.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(), // random non-existent id
      body: {
        username: "does_not_matter",
      } satisfies IUser.IUpdate,
    })
  );
}

