import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";
import type { IUserRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IUserRole";
import type { IPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IVote";

/**
 * E2E test: Update user profile and validate correct and incorrect update paths.
 *
 * Business context:
 * - Users may update their own profile details (bio, username, email, etc.).
 * - Certain fields such as 'id' and 'created_at' are immutable and cannot be changed.
 * - User update must enforce unique constraints on username/email.
 * - If trying to update a user that does not exist, API must return 404.
 *
 * Test process:
 * 1. Create a valid user.
 * 2. Update user profile with valid field changes (e.g., username, email, bio, status). Assert fields are updated and timestamps are refreshed.
 * 3. Attempt to update immutable/restricted fields ('id', 'created_at'); expect API rejection (error or ignored update).
 * 4. Try updating with a duplicate username/email (should fail with unique constraint error).
 * 5. Attempt update on non-existent user (random UUID); expect 404 error.
 */
export async function test_api_core_test_update_user_profile_success_and_failure(
  connection: api.IConnection,
) {
  // Utility function: make a random status
  const randomStatus = () =>
    RandomGenerator.pick([
      "active",
      "pending",
      "suspended",
      "banned",
    ]);
  // For guaranteed uniqueness
  const randomEmail = () =>
    `${RandomGenerator.alphaNumeric(8)}@wrtnlabs.com`;
  const randomUsername = () =>
    `testuser_${RandomGenerator.alphaNumeric(6)}`;

  // Get candidate user role id (simulate or pick arbitrarily common role id; in real E2E may need a lookup)
  // For this test, we can use a random uuid for user_role_id, trusting test DB has role or simulator accepts it.
  const userRoleId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();

  // 1. Create a valid user
  const user = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: userRoleId,
      username: randomUsername(),
      email: randomEmail(),
      bio: "Original bio",
      password: RandomGenerator.alphaNumeric(12),
      status: randomStatus(),
    },
  });
  typia.assert(user);

  // 2. Update user with valid changes
  const newEmail = randomEmail();
  const newUsername = randomUsername();
  const newBio = "Updated bio here";
  const newStatus = randomStatus();

  const updated = await api.functional.core.users.putById(connection, {
    id: user.id,
    body: {
      username: newUsername,
      email: newEmail,
      bio: newBio,
      status: newStatus,
    },
  });
  typia.assert(updated);
  TestValidator.equals("updated username")(newUsername)(updated.username);
  TestValidator.equals("updated email")(newEmail)(updated.email);
  TestValidator.equals("updated bio")(newBio)(updated.bio);
  TestValidator.equals("updated status")(newStatus)(updated.status);
  TestValidator.notEquals("updated_at changed")(user.updated_at)(updated.updated_at);

  // 3. Attempt to update immutable/restricted fields (id, created_at)
  await TestValidator.error("cannot update immutable fields")(() =>
    api.functional.core.users.putById(connection, {
      id: user.id,
      body: {
        // Attempt fields not allowed by IUser.IUpdate; typescript prevents sending id/created_at,
        // so skip actual TS violation (per requirements). Documented here for completeness.
        // If the API incorrectly allows it via request body, that's an implementation flaw.
        // Only send allowed fields. We can test by sending updated_at manually (which is allowed in type but should be ignored by server)
        updated_at: new Date().toISOString(),
      },
    })
  );

  // 4. Create another user to test unique constraint
  const user2 = await api.functional.core.users.post(connection, {
    body: {
      user_role_id: userRoleId,
      username: randomUsername(),
      email: randomEmail(),
      bio: null,
      password: RandomGenerator.alphaNumeric(12),
      status: randomStatus(),
    },
  });
  typia.assert(user2);

  await TestValidator.error("unique username/email update should fail")(() =>
    api.functional.core.users.putById(connection, {
      id: user2.id,
      body: {
        username: updated.username, // duplicate username
        email: updated.email, // duplicate email
      },
    })
  );

  // 5. Attempt update on non-existent user
  await TestValidator.error("update non-existent user should 404")(() =>
    api.functional.core.users.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        username: randomUsername(),
      },
    })
  );
}

