import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";
import type { IUserRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IUserRole";
import type { IPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IVote";

/**
 * E2E test for user deletion covering soft and hard delete scenarios.
 *
 * This test verifies:
 * 1. Successful deletion of an existing user (soft or hard delete semantics).
 * 2. Inaccessibility or status change of the user after deletion.
 * 3. Proper error handling when attempting to delete a non-existent user.
 *
 * Steps:
 * 1. Create a new user via POST /core/users.
 * 2. DELETE the user with /core/users/{id} (soft/hard delete).
 * 3. Attempt to DELETE again and verify appropriate error/status (user already deleted/inaccessible).
 * 4. Attempt to delete a random non-existent user and expect a 404 or similar error response.
 */
export async function test_api_core_test_delete_user_soft_and_hard(connection: api.IConnection) {
  // 1. Create a test user
  const userInput: IUser.ICreate = {
    user_role_id: typia.random<string & tags.Format<"uuid">>(),
    username: RandomGenerator.alphaNumeric(10),
    email: typia.random<string & tags.Format<"email">>(),
    bio: null,
    password: RandomGenerator.alphaNumeric(12),
    status: "active",
  };
  const created = await api.functional.core.users.post(connection, { body: userInput });
  typia.assert(created);

  // 2. Delete the user (soft/hard delete)
  const delResp = await api.functional.core.users.eraseById(connection, {
    id: created.id,
  });
  typia.assert(delResp);
  TestValidator.equals("deleted id")(created.id)(delResp.id ?? created.id);
  if (delResp.status !== undefined)
    TestValidator.predicate("deleted status is not active")(
      delResp.status !== "active"
    );

  // 3. Attempt to delete again: should error or signal already deleted
  await TestValidator.error("second delete returns not found or not allowed")(async () => {
    await api.functional.core.users.eraseById(connection, {
      id: created.id,
    });
  });

  // 4. Attempt to delete a non-existent user
  await TestValidator.error("non-existent user returns not found")(async () => {
    await api.functional.core.users.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    });
  });
}

