 * - Listing all user roles with default pagination.
 * - Filtering roles by a label (using name and description fields) to ensure filtering returns correct results, including no-result edge cases.
 * - Pagination boundaries, including requesting a page beyond available results to ensure an empty data array and correct page metadata.
 *
 * Steps:
 * 1. Fetch all user roles without any filters or pagination parameters, and validate response structure, page counts, and that all roles are returned.
 * 2. If at least one role exists, select a substring from a role's name to use as the search term and request roles filtered by name. Verify that only roles matching the substring appear in the filtered result.
 * 3. Attempt to filter roles with a random unlikely string, ensuring the data array is empty but the rest of the pagination object remains valid.
 * 4. Request a page number far greater than known available pages, confirming the data array is empty and page/pagination metadata is set properly.
 */
export async function test_api_core_test_list_user_roles_with_filtering_and_pagination(
  connection: api.IConnection,
) {
  // 1. List all user roles (no filters)
  const allRolesPage = await api.functional.core.userRoles.patch(connection, {
    body: {},
  });
  typia.assert(allRolesPage);
  const allRoles = allRolesPage.data;
  const totalPages = allRolesPage.pagination.pages;
  const totalRecords = allRolesPage.pagination.records;

  // Sanity check: data length matches total records if total fits in first page
  if (allRolesPage.pagination.current === 1 && allRoles.length < allRolesPage.pagination.limit) {
    TestValidator.equals("total record count matches data array")(allRoles.length)(allRolesPage.pagination.records);
  }
  TestValidator.predicate("roles is array")(
    Array.isArray(allRoles)
  );

  // 2. Filter roles by substring (if there are any roles available)
  if (allRoles.length > 0) {
    // Use a substring of the first role name as a search query
    const roleLabel = allRoles[0].name;
    const partialLabel = roleLabel.substring(0, Math.floor(roleLabel.length / 2)) || roleLabel;
    const filteredPage = await api.functional.core.userRoles.patch(connection, {
      body: { search: partialLabel },
    });
    typia.assert(filteredPage);
    // Check that every returned role has the substring in name or description
    for (const role of filteredPage.data) {
      if (!(
        role.name.includes(partialLabel) ||
        role.description.includes(partialLabel)
      )) {
        throw new Error(`Role does not match filter: ${role.name} / ${role.description}`);
      }
    }
    // If at least one filtered result, its id should be in the unfiltered list
    if (filteredPage.data.length > 0) {
      for (const filteredRole of filteredPage.data) {
        TestValidator.predicate("filtered role exists in master list")(
          allRoles.some((r) => r.id === filteredRole.id)
        );
      }
    }
  }

  // 3. Filtering with a random string (should return 0 results)
  const unlikelyString = `unlikely_${Date.now()}`;
  const noMatchPage = await api.functional.core.userRoles.patch(connection, {
    body: { search: unlikelyString },
  });
  typia.assert(noMatchPage);
  TestValidator.equals("no match data array length")(0)(noMatchPage.data.length);

  // 4. Requesting a page number far beyond available data
  const impossiblePage = await api.functional.core.userRoles.patch(connection, {
    body: { page: 9999, limit: 10 },
  });
  typia.assert(impossiblePage);
  TestValidator.equals("empty data on out of bounds page")(0)(impossiblePage.data.length);
}

