import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IUserRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IUserRole";
import type { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";

/**
 * Validate creating a user role and check for uniqueness and required fields.
 * 
 * This test ensures the following:
 * 1. A user role can be created with a unique name and valid description.
 * 2. Creating a user role with a duplicate name fails (uniqueness constraint).
 * 3. Creating a role with missing required fields (name/description) fails.
 * 
 * Steps:
 * 1. Create a role with a unique random name and description. Assert success and check fields.
 * 2. Attempt to create a new role with the same name and any description. Assert an error occurs (uniqueness enforced).
 * 3. Attempt to create roles missing required fields (name, description, or both). Assert validation error occurs for each case.
 */
export async function test_api_core_test_create_user_role_validation_and_uniqueness(
  connection: api.IConnection,
) {
  // 1. Successfully create a user role with unique name and description
  const uniqueRoleName = RandomGenerator.alphaNumeric(8);
  const description = RandomGenerator.paragraph()(2);
  const createdRole = await api.functional.core.userRoles.post(connection, {
    body: {
      name: uniqueRoleName,
      description
    } satisfies IUserRole.ICreate
  });
  typia.assert(createdRole);
  TestValidator.equals("role name")(uniqueRoleName)(createdRole.name);
  TestValidator.equals("role description")(description)(createdRole.description);

  // 2. Attempt to create a role with the exact same name (should fail uniqueness)
  await TestValidator.error("duplicate role name should fail")(() =>
    api.functional.core.userRoles.post(connection, {
      body: {
        name: uniqueRoleName,
        description: RandomGenerator.paragraph()(2)
      } satisfies IUserRole.ICreate
    })
  );

  // 3. Missing required field: name
  await TestValidator.error("missing name should fail")(() =>
    api.functional.core.userRoles.post(connection, {
      body: {
        // name omitted intentionally
        description: RandomGenerator.paragraph()(2)
      } as any
    })
  );

  // 4. Missing required field: description
  await TestValidator.error("missing description should fail")(() =>
    api.functional.core.userRoles.post(connection, {
      body: {
        name: RandomGenerator.alphaNumeric(8)
        // description omitted intentionally
      } as any
    })
  );

  // 5. Missing both required fields
  await TestValidator.error("missing both fields should fail")(() =>
    api.functional.core.userRoles.post(connection, {
      body: {} as any
    })
  );
}

