import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IUserRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IUserRole";
import type { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";

/**
 * Validates editing user role label and description, and error detection.
 *
 * - Set up a baseline user role via creation (used for update and duplicate tests).
 * - Update the role's label and description using valid input.
 * - Fetch the updated user role and verify the fields have changed.
 * - Attempt to update a non-existent role, expect 404 error.
 * - Attempt to update another role with a label already used by an existing role, expect duplicate error.
 *
 * Steps:
 * 1. Create a baseline user role (roleA)
 * 2. Update roleA's name and description; verify result
 * 3. Attempt to update random-nonexistent role id; ensure 404
 * 4. Create a second user role (roleB)
 * 5. Attempt to update roleB to have the same 'name' as roleA; ensure duplicate error
 */
export async function test_api_core_test_update_user_role_with_valid_and_invalid_input(
  connection: api.IConnection,
) {
  // 1. Create a baseline user role (roleA)
  const roleAInput = {
    name: RandomGenerator.alphaNumeric(8),
    description: RandomGenerator.paragraph()(),
  } satisfies IUserRole.ICreate;
  const roleA = await api.functional.core.userRoles.post(connection, { body: roleAInput });
  typia.assert(roleA);

  // 2. Update roleA's name and description; verify change
  const roleAUpdate = {
    name: RandomGenerator.alphaNumeric(8),
    description: RandomGenerator.paragraph()(),
  } satisfies IUserRole.IUpdate;
  const updatedRoleA = await api.functional.core.userRoles.putById(connection, { id: roleA.id, body: roleAUpdate });
  typia.assert(updatedRoleA);
  TestValidator.equals("updated name")(roleAUpdate.name)(updatedRoleA.name);
  TestValidator.equals("updated description")(roleAUpdate.description)(updatedRoleA.description);

  // 3. Attempt to update a non-existent role and expect 404
  await TestValidator.error("non-existent user role update should 404")(() =>
    api.functional.core.userRoles.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { name: RandomGenerator.alphaNumeric(8) } as IUserRole.IUpdate,
    })
  );

  // 4. Create roleB for duplicate name test
  const roleBInput = {
    name: RandomGenerator.alphaNumeric(10),
    description: RandomGenerator.paragraph()(),
  } satisfies IUserRole.ICreate;
  const roleB = await api.functional.core.userRoles.post(connection, { body: roleBInput });
  typia.assert(roleB);

  // 5. Attempt to update roleB with name identical to updated roleA, expect duplicate error
  await TestValidator.error("duplicate user role name")(() =>
    api.functional.core.userRoles.putById(connection, {
      id: roleB.id,
      body: { name: updatedRoleA.name } as IUserRole.IUpdate,
    })
  );
}

