import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IUserRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IUserRole";
import type { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";

/**
 * End-to-end test for deletion of user roles with dependency validations.
 *
 * This test covers the following scenarios:
 * 1. Successfully deleting an unused user role and verifying it is removed from the system.
 * 2. Attempting to delete a user role that is still referenced (assigned to a user) and verifying business logic enforcement (should reject deletion or return clear status).
 * 3. Attempting to delete a non-existent user role and asserting that the proper error is returned.
 *
 * Steps:
 * 1. Create a user role to be deleted in the successful case.
 * 2. Delete that role using the DELETE endpoint and verify deletion response.
 * 3. Attempt to re-fetch or delete it again and ensure appropriate error/response.
 * 4. Create another user role and (hypothetically) assign it to a user (cannot perform assignment here without user entity write access, so this part is a place-holder and commented for future coverage.)
 * 5. Attempt to delete a user role with a fake user assignment (simulate or expect business logic rejection if dependency enforcement active).
 * 6. Attempt to delete a random non-existent role and assert error returned.
 */
export async function test_api_userRoles_test_delete_user_role_with_dependency_check(connection: api.IConnection) {
  // 1. Create a user role
  const unusedRole = await api.functional.core.userRoles.post(connection, {
    body: {
      name: `test_role_${RandomGenerator.alphaNumeric(8)}`,
      description: "Role for deletion test",
    } satisfies IUserRole.ICreate,
  });
  typia.assert(unusedRole);

  // 2. Delete the new role
  const deleteResp = await api.functional.core.userRoles.eraseById(connection, {
    id: unusedRole.id,
  });
  typia.assert(deleteResp);
  TestValidator.equals("id matches")(unusedRole.id)(deleteResp.id ?? "");
  TestValidator.predicate("status deleted")(deleteResp.status === undefined || /deleted/i.test(deleteResp.status!));

  // 3. Attempt to delete again (should error/not found)
  await TestValidator.error("Deleting already deleted role should fail")(() =>
    api.functional.core.userRoles.eraseById(connection, { id: unusedRole.id })
  );

  // 4. Attempt to delete a non-existent role
  await TestValidator.error("Deleting non-existent role should fail")(() =>
    api.functional.core.userRoles.eraseById(connection, { id: typia.random<string & tags.Format<"uuid">>() })
  );

  // 5. Optionally: If user assignment APIs are available, create a role, assign to a user, then try to delete and assert fail. Skipped here due to assignment API unavailability.
}

