import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICategory } from "@ORGANIZATION/PROJECT-api/lib/structures/ICategory";
import type { IPageICategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageICategory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 카테고리 목록/검색 API의 페이지네이션 및 필터 기능을 검증하는 테스트입니다.
 *
 * - 기본 페이지네이션 파라미터로 정상 목록 조회
 * - 커스텀 파라미터로 다양한 limit/page 조합의 페이지네이션 결과 확인
 * - 존재하는(정확히 일치되는) name 또는 description 필터 사용 검색 결과 검증
 * - 존재하지 않는 페이지 요청 시 빈 데이터 배열 반환되는지 검증
 *
 * 1. 더미 카테고리를 3개 등록해 이름ㆍ설명을 미리 파악한다.
 * 2. 기본 요청(page:1, limit:100)으로 전체 카테고리 목록 조회 시, 위에서 등록한 3개 포함 여부 확인
 * 3. 커스텀 limit/page 조합(page:2, limit:2)으로 페이지 분할 결과 및 카운트 메타 검증
 * 4. 특정 name 필터(예: 첫 번째 카테고리 이름)로 검색 시 정상 1건 반환 여부 확인
 * 5. 특정 description 필터로 부분 일치 검색(예: '테스트') 결과 확인.     
 * 6. 실제 pageCount+1의 page 번호로 요청 시 data가 비어 있는지 검증
 */
export async function test_api_core_test_list_categories_with_pagination_and_filters(connection: api.IConnection) {
  // 1. 테스트 카테고리 3개 등록 (고유 name/description 미리 지정)
  const testCategories = await Promise.all([
    api.functional.core.categories.create(connection, { body: { name: `카테고리A_${RandomGenerator.alphaNumeric(6)}`, description: "테스트A", } }),
    api.functional.core.categories.create(connection, { body: { name: `카테고리B_${RandomGenerator.alphaNumeric(6)}`, description: "테스트B", } }),
    api.functional.core.categories.create(connection, { body: { name: `카테고리C_${RandomGenerator.alphaNumeric(6)}`, description: "샘플C",   } }),
  ]);

  // 2. 기본 요청(page:1, limit:100)으로 전체 목록 조회
  const page1 = await api.functional.core.categories.patch(connection, { body: { page: 1, limit: 100 } });
  typia.assert(page1);
  // 등록한 3개 모두 포함됐는지 확인
  for (const c of testCategories) TestValidator.predicate(`${c.name} 존재`)(page1.data.some(e => e.name === c.name));
  // 전체 수 및 메타
  TestValidator.predicate("페이지네이션 메타")(
    page1.pagination.current === 1 && page1.pagination.limit === 100 && Array.isArray(page1.data)
  );

  // 3. 커스텀 limit/page 조합으로(페이지 분할 테스트)
  const page2 = await api.functional.core.categories.patch(connection, { body: { page: 2, limit: 2 } });
  typia.assert(page2);
  TestValidator.equals("limit")(2)(page2.pagination.limit);
  // 전체가 3개였다면, 2페이지는 1개만 있을 것 (남은 1개)
  TestValidator.equals("2페이지 데이터 수")(1)(page2.data.length);

  // 4. name 필터(정확 매치)
  const nameMatch = await api.functional.core.categories.patch(connection, { body: { name: testCategories[0].name, page: 1, limit: 10 } });
  typia.assert(nameMatch);
  TestValidator.equals("특정 name 매치 결과 수")(1)(nameMatch.data.length);
  TestValidator.equals("name 일치")(testCategories[0].name)(nameMatch.data[0].name);

  // 5. description 부분 일치
  const descPartial = await api.functional.core.categories.patch(connection, { body: { description: "테스트", page: 1, limit: 10 } });
  typia.assert(descPartial);
  // "테스트A", "테스트B"가 모두 걸려야 함
  TestValidator.predicate("description 부분 일치 수")(descPartial.data.length >= 2);

  // 6. 없는 page(페이지 초과) 번호로 조회하면 data 빈 배열
  const outOfBounds = await api.functional.core.categories.patch(connection, { body: { page: page1.pagination.pages + 1, limit: 100 } });
  typia.assert(outOfBounds);
  TestValidator.equals("빈 페이지 data")(0)(outOfBounds.data.length);
}

