import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICategory } from "@ORGANIZATION/PROJECT-api/lib/structures/ICategory";

/**
 * 카테고리 수정 API E2E 테스트 (정상/비정상 시나리오)
 *
 * 1. 정상적으로 기존 카테고리의 이름/설명을 수정할 수 있다.
 * 2. 이미 존재하는 이름(고유값)으로 수정하려 할 때 유니크 제약 오류가 발생한다.
 * 3. 존재하지 않는 카테고리에 대해 수정 요청 시 올바른 오류(예: 404)가 반환된다.
 *
 * [Step-by-step]
 * 1. 이름과 설명이 다른 카테고리 두 개(A, B)를 생성한다.
 * 2. 카테고리A의 이름/설명을 정상적으로 변경한다(성공 시 name/description 모두 반영 확인).
 * 3. 카테고리B의 이름을 이미 존재하는 이름(카테고리A의 변경 후 이름)으로 바꾸려 시도하고, Unique 제약 오류를 확인한다.
 * 4. 무작위(존재하지 않는) id로 수정 요청 시 적절한 오류(404 등)를 확인한다.
 */
export async function test_api_core_test_update_category_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. 샘플 카테고리 두 개 생성 (A, B)
  const categoryA = await api.functional.core.categories.post(connection, {
    body: {
      name: "카테고리A",
      description: "테스트용 카테고리A"
    }
  });
  typia.assert(categoryA);

  const categoryB = await api.functional.core.categories.post(connection, {
    body: {
      name: "카테고리B",
      description: "테스트용 카테고리B"
    }
  });
  typia.assert(categoryB);

  // 2. 카테고리A의 이름/설명을 정상적으로 수정(성공)
  const updatedName = "카테고리A-수정";
  const updatedDescription = "카테고리A 설명 수정";
  const updated = await api.functional.core.categories.putById(connection, {
    id: categoryA.id,
    body: {
      name: updatedName,
      description: updatedDescription,
    }
  });
  typia.assert(updated);
  TestValidator.equals("updated category name")(updatedName)(updated.name);
  TestValidator.equals("updated category description")(updatedDescription)(updated.description);

  // 3. 유니크 제약 위반: 카테고리B의 이름을 이미 존재하는 이름으로 변경 시도
  await TestValidator.error("category name unique constraint")(() =>
    api.functional.core.categories.putById(connection, {
      id: categoryB.id,
      body: {
        name: updatedName, // 중복 이름
      },
    })
  );

  // 4. 존재하지 않는 id로 수정 시도
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("update non-existent category should fail")(() =>
    api.functional.core.categories.putById(connection, {
      id: nonExistentId,
      body: {
        name: "없는카테고리",
      },
    })
  );
}

