 * 4. (연관성 제약) 임의로 새 카테고리를 추가한 뒤, 해당 카테고리를 타 엔티티(게시글 등)에서 참조 중인 상태에서 삭제 시도를 하면, 외래키/의존 관계로 인해 삭제가 거부되어야 한다. (실제 게시글 생성 API가 존재 시 함께 테스트)
 * 5. 존재하지 않는 랜덤 uuid에 대해 삭제 시도 시 마찬가지로 실패 반환됨을 검증한다.
 */
export async function test_api_core_test_delete_category_with_and_without_dependencies(connection: api.IConnection) {
  // 1. 카테고리 생성 (삭제 테스트용)
  const createBody: ICategory.ICreate = {
    name: RandomGenerator.alphabets(8),
    description: RandomGenerator.paragraph()(16)
  };
  const category = await api.functional.core.categories.post(connection, { body: createBody });
  typia.assert(category);

  // 2. 정상 삭제 및 목록 제외 검증
  const delResult = await api.functional.core.categories.eraseById(connection, { id: category.id });
  typia.assert(delResult);
  TestValidator.predicate("Category deleted")(delResult.success === true);

  // 3. 동일 id 재삭제 시도 (존재하지 않음 에러 검증)
  const secondDel = await api.functional.core.categories.eraseById(connection, { id: category.id });
  typia.assert(secondDel);
  TestValidator.predicate("2nd delete fails")(secondDel.success === false);

  // 4. 의존성 제약(참조 중) 삭제 거부 검증
  // [TODO: 실제 게시글 등 엔티티 생성 후 삭제 시도 구현 필요 - 해당 API 존재 시 구현]

  // 5. 랜덤 UUID로 존재하지 않는 항목 삭제 시도
  const randomId = typia.random<string & tags.Format<"uuid">>();
  const notFoundDel = await api.functional.core.categories.eraseById(connection, { id: randomId });
  typia.assert(notFoundDel);
  TestValidator.predicate("not found delete fails")(notFoundDel.success === false);
}

