import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICategory } from "@ORGANIZATION/PROJECT-api/lib/structures/ICategory";

/**
 * 카테고리 삭제 및 연관성 제약 검증 E2E 테스트
 *
 * 1. 임시로 신규 카테고리 생성 후 삭제가 정상적으로 이뤄지는지 확인
 * 2. 삭제된 카테고리를 한 번 더 삭제 시도해서, 이미 없는 id 삭제 시도 결과가 실패하는지 확인
 * 3. 실제 존재하지 않는 랜덤 uuid로 삭제 시도하여 실패 응답 확인
 * 4. (의존성 제약 테스트: 타 엔티티에서 참조중인 카테고리 삭제 시도 → 실패, 단 관련 엔티티/테스트 API 동시 필요)
 */
export async function test_api_core_test_delete_category_with_and_without_dependencies(
  connection: api.IConnection,
) {
  // 1. 테스트용 카테고리 생성
  const createBody: ICategory.ICreate = {
    name: RandomGenerator.alphabets(8),
    description: RandomGenerator.paragraph()(16),
  };
  const category = await api.functional.core.categories.post(connection, {
    body: createBody,
  });
  typia.assert(category);

  // 2. 생성한 카테고리 정상 삭제 → 삭제 성공 플래그 확인
  const delResult = await api.functional.core.categories.eraseById(connection, {
    id: category.id,
  });
  typia.assert(delResult);
  TestValidator.predicate("category successfully deleted")(delResult.success === true);

  // 3. 동일 id로 재삭제 시도 → 실패(expected: 이미 삭제됨/존재하지 않음)
  const secondDel = await api.functional.core.categories.eraseById(connection, {
    id: category.id,
  });
  typia.assert(secondDel);
  TestValidator.predicate("2nd delete returns fail")(secondDel.success === false);

  // 4. 임의의 존재하지 않는 uuid로 삭제 시도 → 실패 반환
  const randomId = typia.random<string & tags.Format<"uuid">>();
  const notFoundDel = await api.functional.core.categories.eraseById(connection, {
    id: randomId,
  });
  typia.assert(notFoundDel);
  TestValidator.predicate("random id delete returns fail")(notFoundDel.success === false);

  // 5. (의존성 제약) 타 엔티티에서 참조 중인 카테고리 삭제 → 실패 (실제 게시글/참조 데이터 생성 API 있을 경우)
