import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPost";
import type { IPageIPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 게시글 목록 조회 (filter, pagination, ordering) E2E 테스트
 *
 * 다양한 조건(카테고리, 작성자, 제목/본문 키워드, 기간) 필터와
 * 페이지네이션 및 정렬 옵션을 사용해 posts.patch 엔드포인트의 동작을
 * 검증한다.
 *
 * 검증 범주:
 *  - 각 필터 동작 정확성(카테고리, 작성자, 키워드, 기간)
 *  - 페이징(page/limit) 작동 및 meta 일관성
 *  - 정렬(최신순) 일치 여부
 *  - 결과 없음 시 빈 배열·meta 구조 반환
 *
 * [사전조건]
 * 실제로는 별도 post 생성 API를 사용해 고유한 필드 조합(카테고리ID, userID 등)과
 * 시간대가 다른 5개 게시글을 등록하는 것이 정석이지만
 *(여기서는 조회 검증만 담당하며, fixture 데이터가 이미 존재한다고 가정)
 *
 * 1. 카테고리별 필터 → 해당 카테고리 게시글만 반환
 * 2. 작성자별 필터 → 해당 작성자 게시글만 반환
 * 3. 제목/본문 키워드 검색 → 부분일치 글만 반환
 * 4. 생성일기간(From~To) → 지정범위 내 글만 반환
 * 5. 페이지네이션(page & limit=2) → 두 페이지로 분할 수/순서 검증, 초과 조회 시 빈배열
 * 6. (기본) 최신순 정렬 확인
 */
export async function test_api_posts_test_list_posts_with_varied_filters_and_pagination(
  connection: api.IConnection,
) {
  // 테스트에서 사용된 고유값 세팅 (실제 fixture 데이터에 맞게 uuid·닉네임·category 값을 입력해야 함)
  const CATEGORY_ID_1 = "00000000-0000-0000-0000-000000000101" as string;
  const CATEGORY_ID_2 = "00000000-0000-0000-0000-000000000102" as string;
  const AUTHOR_ID_1 = "00000000-0000-0000-0000-000000001001" as string;
  const AUTHOR_ID_2 = "00000000-0000-0000-0000-000000001002" as string;
  const TITLE_KEYWORD = "특수키워드";
  const CONTENT_KEYWORD = "본문특이값";
  const CREATED_FROM = "2025-07-01T00:00:00.000Z";
  const CREATED_TO = "2025-07-09T23:59:59.999Z";

  // 1. 카테고리별 필터링
  {
    const res = await api.functional.posts.posts.patch(connection, {
      body: {
        category_id: CATEGORY_ID_1,
        page: 1,
        limit: 10,
      },
    });
    typia.assert(res);
    // 전체 글 리스트에서 카테고리ID 일치 여부 확인
    TestValidator.predicate("category_id 필터 동작")(res.data.every(post => post.category_id === CATEGORY_ID_1));
  }

  // 2. 작성자별 필터링
  {
    const res = await api.functional.posts.posts.patch(connection, {
      body: {
        user_id: AUTHOR_ID_2,
        page: 1,
        limit: 10,
      },
    });
    typia.assert(res);
    TestValidator.predicate("user_id 필터 동작")(res.data.every(post => post.user_id === AUTHOR_ID_2));
  }

  // 3. 제목 키워드 검색
  {
    const res = await api.functional.posts.posts.patch(connection, {
      body: {
        title: TITLE_KEYWORD,
        page: 1,
        limit: 10,
      },
    });
    typia.assert(res);
    TestValidator.predicate("제목 부분검색")(res.data.every(post => post.title.includes(TITLE_KEYWORD)));
  }

  // 4. 본문 키워드 검색
  {
    const res = await api.functional.posts.posts.patch(connection, {
      body: {
        content: CONTENT_KEYWORD,
        page: 1,
        limit: 10,
      },
    });
    typia.assert(res);
    TestValidator.predicate("본문 부분검색")(res.data.every(post => post.content.includes(CONTENT_KEYWORD)));
  }

  // 5. 생성일 범위(기간) 검색
  {
    const res = await api.functional.posts.posts.patch(connection, {
      body: {
        created_from: CREATED_FROM,
        created_to: CREATED_TO,
        page: 1,
        limit: 10,
      },
    });
    typia.assert(res);
    TestValidator.predicate("생성일 범위필터")(res.data.every(post => post.created_at >= CREATED_FROM && post.created_at <= CREATED_TO));
  }

  // 6. 페이지네이션 및 과도 페이지 요청 검사
  {
    // page 1 (limit 2)
    const page1 = await api.functional.posts.posts.patch(connection, {
      body: {
        page: 1,
        limit: 2,
      },
    });
    typia.assert(page1);
    TestValidator.equals("pagination.limit==2")(2)(page1.pagination.limit);
    TestValidator.equals("pagination.current==1")(1)(page1.pagination.current);
    // page 2
    const page2 = await api.functional.posts.posts.patch(connection, {
      body: {
        page: 2,
        limit: 2,
      },
    });
    typia.assert(page2);
    TestValidator.equals("pagination.limit==2")(2)(page2.pagination.limit);
    TestValidator.equals("pagination.current==2")(2)(page2.pagination.current);
    // page overflow (존재하지 않는 100페이지)
    const overflow = await api.functional.posts.posts.patch(connection, {
      body: {
        page: 100,
        limit: 2,
      },
    });
    typia.assert(overflow);
    TestValidator.equals("empty data on overflow")(0)(overflow.data.length);
  }

  // 7. 최신순(생성일 내림차순) 정렬 검증 (기본 추정)
  {
    const res = await api.functional.posts.posts.patch(connection, {
      body: {
        page: 1,
        limit: 10,
      },
    });
    typia.assert(res);
    // 최신순 내림차순 확인 (created_at 이 큰 게 앞에 와야 함)
    const sorted = res.data.slice().sort((a, b) => b.created_at.localeCompare(a.created_at));
    TestValidator.equals("created_at 내림차순 정렬")(sorted.map(p=>p.id))(res.data.map(p=>p.id));
  }
}

