import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPost";

/**
 * Validate getting a post by ID.
 *
 * 1. First, create a new post using the posts/posts POST endpoint.
 * 2. Retrieve the post with the returned id (GET /posts/posts/{id}) - assert all major fields match.
 * 3. Attempt to fetch a post by a random UUID not associated to any post - should result in 404 error.
 */
export async function test_api_posts_test_get_post_by_id_success_and_not_found(
  connection: api.IConnection,
) {
  // 1. Create a post
  const createInput: IPost.ICreate = {
    category_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(),
    content: RandomGenerator.content()()(),
    user_id: typia.random<string & tags.Format<"uuid">>(),
  };
  const created: IPost = await api.functional.posts.posts.post(connection, {
    body: createInput,
  });
  typia.assert(created);
  // 2. Retrieve the post by ID and validate fields
  const fetched: IPost = await api.functional.posts.posts.getById(connection, {
    id: created.id,
  });
  typia.assert(fetched);
  TestValidator.equals("id")(created.id)(fetched.id);
  TestValidator.equals("title")(createInput.title)(fetched.title);
  TestValidator.equals("content")(createInput.content)(fetched.content);
  TestValidator.equals("category_id")(createInput.category_id)(fetched.category_id);
  TestValidator.equals("user_id")(createInput.user_id)(fetched.user_id);
  // 3. Attempt to GET non-existent post
  await TestValidator.error("should be 404 for not found")(() =>
    api.functional.posts.posts.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    }),
  );
}

