import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPost";

/**
 * 게시글 생성의 정상, 실패(필수 입력값 누락), 중복(제약 시) 시나리오를 검증하는 통합 E2E 테스트
 *
 * - 목적: 모든 필수 입력값으로 정상 생성, 필수 필드 누락시 Validation Error, 동일 입력값 반복 시 오류(중복 제약 시) 여부
 * - 주요 필드: category_id, title, content, user_id
 * - 비즈니스 규칙(제약)은 실제 백엔드 정책에 따라 다를 수 있음
 *
 * 절차:
 * 1. 필수값 입력으로 정상적인 게시글을 생성한다 (입력과 반환값 일치 확인)
 * 2. 필수 필드 중 하나씩 누락하여 API 요청 시도 → Validation Error 기대
 * 3. 동일한 입력값으로 다시 생성 → 중복/고유값 제약 정책 적용 시 오류 기대
 */
export async function test_api_posts_test_create_post_with_valid_and_invalid_requests(
  connection: api.IConnection,
) {
  // 1. 정상: 모든 필수 필드로 게시글 생성
  const postInput = {
    category_id: typia.random<string & tags.Format<"uuid">>(),
    title: "E2E 테스트 게시글 제목",
    content: "이것은 E2E 통합테스트용 게시글 본문입니다.",
    user_id: typia.random<string & tags.Format<"uuid">>(),
  } satisfies IPost.ICreate;

  const created = await api.functional.posts.posts.post(connection, { body: postInput });
  typia.assert(created);
  TestValidator.equals("title")(postInput.title)(created.title);
  TestValidator.equals("content")(postInput.content)(created.content);
  TestValidator.equals("category_id")(postInput.category_id)(created.category_id);
  TestValidator.equals("user_id")(postInput.user_id)(created.user_id);

  // 2. 필수 필드 누락값 개별별로 Validation Error 검증 (TS 수준에서는 테스트 불가 → 런타임 시도)
  type Mandatory = keyof IPost.ICreate;
  (['category_id', 'title', 'content', 'user_id'] as Mandatory[]).forEach(async (field) => {
    const invalid = { ...postInput };
    // @ts-expect-error: 테스트 목적 일부 필드 의도적 제거
    delete invalid[field];
    await TestValidator.error(`Post 생성 시 ${field} 누락 Validation Error`)(async () => {
      return api.functional.posts.posts.post(connection, { body: invalid });
    });
  });

  // 3. 동일 입력값으로 중복 생성 시도 (유니크/고유 제약이 시스템에 존재한다면)
  await TestValidator.error("동일 데이터로 게시글 중복 생성 시도 - 중복 제약 정책 적용 시 오류")(async () => {
    return api.functional.posts.posts.post(connection, { body: postInput });
  });
}

