  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const userId = typia.random<string & tags.Format<"uuid">>();
  const postCreateInput: IPost.ICreate = {
    category_id: categoryId,
    title: "처음 제목",
    content: "최초 본문입니다.",
    user_id: userId,
  };
  const post = await api.functional.posts.posts.post(connection, { body: postCreateInput });
  typia.assert(post);

  // 2. 제목/본문/카테고리 정상 수정 케이스
  const updateInput: IPost.IUpdate = {
    title: "제목-수정",
    content: "수정된 본문 내용.",
    category_id: typia.random<string & tags.Format<"uuid">>(), // 랜덤 새 카테고리
  };
  const updated = await api.functional.posts.posts.putById(connection, {
    id: post.id,
    body: updateInput,
  });
  typia.assert(updated);
  TestValidator.equals("updated.title")(updateInput.title)(updated.title);
  TestValidator.equals("updated.content")(updateInput.content)(updated.content);
  TestValidator.equals("updated.category_id")(updateInput.category_id)(updated.category_id);

  // 3. 불변(immutable) 필드 포함해 update 요청 (실패 예상)
  await TestValidator.error("immutable fields must cause error")(() =>
    api.functional.posts.posts.putById(connection, {
      id: post.id,
      body: { ...updateInput, id: typia.random<string & tags.Format<"uuid">>() } as any,
    })
  );
  await TestValidator.error("immutable user_id must cause error")(() =>
    api.functional.posts.posts.putById(connection, {
      id: post.id,
      body: { ...updateInput, user_id: typia.random<string & tags.Format<"uuid">>() } as any,
    })
  );
  await TestValidator.error("immutable created_at must cause error")(() =>
    api.functional.posts.posts.putById(connection, {
      id: post.id,
      body: { ...updateInput, created_at: new Date().toISOString() } as any,
    })
  );

  // 4. 무작위 ID로 없는 포스트 수정 요청 (404 기대)
  await TestValidator.error("404 on non-existent post id")(() =>
    api.functional.posts.posts.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: updateInput,
    })
  );
}

