import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPost";

/**
 * 게시글 단건 삭제(EraseById) E2E 테스트
 *
 * 본 테스트는 다음 시나리오를 검증한다:
 * 1. 신규 게시글을 생성한다.
 * 2. 해당 게시글의 ID로 삭제 요청을 보낸다.
 * 3. 삭제 API 성공 응답(success=true, message)에 대한 타입과 의미를 검증한다.
 * 4. 삭제된 게시글이 다시 조회 또는 목록/검색에서 노출되지 않는지 확인한다.
 * 5. 존재하지 않는 게시글 ID로 삭제 시도시, 적절한 에러가 발생함을 검증한다.
 *
 * # 사전 조건
 * - 삭제 테스트 전, 반드시 게시글을 직접 생성하여 id 확보 필요(데이터 독립성 보장)
 * - 게시글 조회 및 목록 관련 API는 존재 여부 확인 시에 필요
 */
export async function test_api_posts_test_delete_post_and_verify_removal(connection: api.IConnection) {
  // 1. 테스트용 게시글 생성
  const createdPost = await api.functional.posts.posts.post(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: "E2E 테스트 게시글 " + RandomGenerator.alphaNumeric(5),
      content: "삭제 테스트를 위한 임시 게시글", 
      user_id: typia.random<string & tags.Format<"uuid">>()
    }
  });
  typia.assert(createdPost);

  // 2. 방금 생성한 게시글 삭제 요청
  const deleteResult = await api.functional.posts.posts.eraseById(connection, {
    id: createdPost.id,
  });
  typia.assert(deleteResult);
  TestValidator.predicate("삭제 성공 플래그 확인")(deleteResult.success === true);

  // 3. 삭제된 게시글이 더 이상 조회되지 않음 확인
  await TestValidator.error("삭제된 게시글 조회 불가")(async () => {
    await api.functional.posts.posts.get(connection, { id: createdPost.id });
  });

  // 4. 존재하지 않는 게시글 ID 삭제 시도 - 임의 uuid 사용
  const nonExistUuid = typia.random<string & tags.Format<"uuid">>();
  const failedDelete = await api.functional.posts.posts.eraseById(connection, {
    id: nonExistUuid,
  });
  typia.assert(failedDelete);
  TestValidator.predicate("존재하지 않는 게시글 삭제 실패")(failedDelete.success === false);
}

