 * 4. 해당 게시글이 더 이상 조회되지 않음을 검증한다.
 * 5. 존재하지 않는 무작위 uuid로 삭제 시도시 실패(예외/오류/ success=false 등)를 검증한다.
 *
 * 게시글 삭제 기능의 정상 동작 뿐만 아니라 존재하지 않는 자원 삭제 상황까지 포괄해 예외 케이스까지 엄밀히 검증한다.
 */
export async function test_api_posts_test_delete_post_and_verify_removal(
  connection: api.IConnection,
) {
  // 1. 테스트용 게시글 생성
  const createdPost = await api.functional.posts.posts.post(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: "E2E 삭제 테스트 " + RandomGenerator.alphaNumeric(6),
      content: "삭제 동작 및 예외 검증용 임시 게시글입니다.",
      user_id: typia.random<string & tags.Format<"uuid">>(),
    },
  });
  typia.assert(createdPost);

  // 2. 해당 게시글의 id로 삭제 수행
  const deleteResult = await api.functional.posts.posts.eraseById(connection, {
    id: createdPost.id,
  });
  typia.assert(deleteResult);
  TestValidator.predicate("삭제 성공")(deleteResult.success === true);

  // 3. 삭제된 게시글이 더 이상 조회/노출되지 않음을 확인(조회 시도시 예외 발생 등)
  await TestValidator.error("삭제된 게시글 재조회시 예외")(async () => {
    await api.functional.posts.posts.get(connection, { id: createdPost.id });
  });

  // 4. 존재하지 않는 임의의 uuid로 삭제 시도 → 실패(응답 success=false 혹은 메시지)
  const nonExistUuid = typia.random<string & tags.Format<"uuid">>();
  const failedDelete = await api.functional.posts.posts.eraseById(connection, {
    id: nonExistUuid,
  });
  typia.assert(failedDelete);
  TestValidator.predicate("존재하지 않는 게시글 삭제 실패")(failedDelete.success === false);
}

