import api from "@ORGANIZATION/PROJECT-api";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IPageIComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for listing comments with and without filters, ensuring correct pagination and empty result handling.
 *
 * Scenario:
 * 1. Query comments with no filters to get a general listing. Validate pagination properties, list content, and type safety.
 * 2. Query comments filtered by a specific post ID and verify all results belong to that post.
 * 3. Query comments filtered by user ID and verify all results are authored by that user.
 * 4. Use pagination (limit, offset) to test result slicing and boundary conditions (edges, after last result).
 * 5. Query with non-existent filter values (e.g., random UUIDs) to confirm empty results and pagination math.
 */
export async function test_api_posts_test_list_comments_with_filters_and_pagination(connection: api.IConnection) {
  // 1. Query comments with no filters
  const noFilterResult = await api.functional.posts.comments.patch(connection, { body: {} });
  typia.assert(noFilterResult);
  TestValidator.predicate("pagination at least one page")(
    noFilterResult.pagination.pages >= 1,
  );
  if (noFilterResult.data.length > 0) {
    // We'll use an existing post_id and user_id for subsequent tests
    const sampleComment = noFilterResult.data[0];
    // 2. Query by post ID
    const byPostResult = await api.functional.posts.comments.patch(connection, { body: { postId: sampleComment.post_id } });
    typia.assert(byPostResult);
    TestValidator.equals("all comments have the same post ID")(
      true,
    )(
      byPostResult.data.every((c) => c.post_id === sampleComment.post_id),
    );
    // 3. Query by user ID
    const byUserResult = await api.functional.posts.comments.patch(connection, { body: { userId: sampleComment.user_id } });
    typia.assert(byUserResult);
    TestValidator.equals("all comments authored by the user")(
      true,
      byUserResult.data.every((c) => c.user_id === sampleComment.user_id),
    );
    // 4. Pagination tests
    const limit = 1;
    const paged = await api.functional.posts.comments.patch(connection, { body: { limit } });
    typia.assert(paged);
    TestValidator.equals("pagination: limit respected")(limit)(paged.data.length);
    // Offset after last
    const beyond = await api.functional.posts.comments.patch(connection, {
      body: { offset: noFilterResult.pagination.records, limit: 5 },
    });
    typia.assert(beyond);
    TestValidator.equals("no data after end of pages")(0)(beyond.data.length);
  } else {
    // 5. Query with random, expected-empty filters
    const emptyPost = await api.functional.posts.comments.patch(connection, {
      body: { postId: typia.random<string & tags.Format<"uuid">>() },
    });
    typia.assert(emptyPost);
    TestValidator.equals("empty with random postId")(0)(emptyPost.data.length);
    // Pagination with offset 0 and non-dat
    const pagedEmpty = await api.functional.posts.comments.patch(connection, { body: { offset: 0, limit: 1 } });
    typia.assert(pagedEmpty);
    TestValidator.equals("empty result: data array should be zero length")(0)(pagedEmpty.data.length);
  }
}

