import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";

/**
 * Test detailed retrieval of a comment by its ID, including both success and error scenarios.
 *
 * This test covers fetching a comment by its unique ID and validating the response, as well as handling the case when an invalid or non-existent ID is requested. Ensures business logic behaves correctly for both retrieval and failure scenarios, as described in the scenario draft.
 *
 * 1. Create a new comment (dependency) via POST /posts/comments, using random but valid values for user_id, post_id, and content.
 * 2. Retrieve the newly created comment by its ID via GET /posts/comments/{id} and verify the response matches expected values and types.
 * 3. Attempt to retrieve a comment using an invalid and/or non-existent ID (e.g., random UUID not used in any record).
 * 4. Validate that the correct error (such as 404 or appropriate business error code) is returned for the invalid ID scenario.
 */
export async function test_api_posts_test_get_comment_details_success_and_failure(
  connection: api.IConnection,
) {
  // 1. Create a new comment with valid random values
  const commentInput: IComment.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    post_id: typia.random<string & tags.Format<"uuid">>(),
    content: RandomGenerator.paragraph()(),
    // parent_id is optional and will be omitted here (null by default)
  };
  const created: IComment = await api.functional.posts.comments.post(
    connection,
    { body: commentInput },
  );
  typia.assert(created);
  // 2. Retrieve the comment by its id
  const result: IComment = await api.functional.posts.comments.getById(
    connection,
    { id: created.id },
  );
  typia.assert(result);
  TestValidator.equals("id matches")(created.id)(result.id);
  TestValidator.equals("content matches")(created.content)(result.content);
  // 3. Attempt to fetch with a random non-existent ID
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("should fail for non-existent id")(() =>
    api.functional.posts.comments.getById(connection, { id: nonExistentId }),
  );
}

