import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";

/**
 * Validates comment creation in various scenarios for Posts domain.
 *
 * This test checks three core paths:
 * 1. Successfully creating a comment on a valid, existing post (using required fields only).
 * 2. Attempting to create a comment for a non-existent post (should result in failure).
 * 3. Attempting to create a comment with required fields omitted (should trigger validation errors).
 *
 * Step-by-step process:
 * 1. Create a new post (dependency, since comments must attach to valid posts).
 * 2. Post a comment to the valid post with all required fields and check success.
 * 3. Try to comment with a random (non-existent) post_id and verify error response.
 * 4. Try to comment with missing required fields (e.g., omit content, post_id, or user_id), expect validation failure.
 *
 * The function ensures API validation logic and business rules are enforced for comments.
 */
export async function test_api_posts_test_create_comment_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Create a post (dependency)
  const user_id = typia.random<string & tags.Format<"uuid">>();
  const category_id = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.posts.posts.post(connection, {
    body: {
      category_id,
      title: RandomGenerator.paragraph()(),
      content: RandomGenerator.content()()(),
      user_id,
    } satisfies IPost.ICreate,
  });
  typia.assert(post);

  // 2. Successfully create a comment on the above post
  const comment = await api.functional.posts.comments.post(connection, {
    body: {
      user_id,
      post_id: post.id,
      content: RandomGenerator.content()()(),
    } satisfies IComment.ICreate,
  });
  typia.assert(comment);
