import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";

/**
 * E2E test to validate comment updating logic, covering successful content edits,
 * attempts to update non-existent/deleted comments, and deletion status updates.
 *
 * Business context:
 * - Comments are made by registered users on posts (with possible threading under parent comments)
 * - Editing a comment is allowed for the author or moderator within business rules
 * - Soft deletion (using deleted_at field) is enforced for moderation purposes
 *
 * Steps to implement:
 * 1. Create a fresh comment via API (dependency)
 * 2. Update the comment's content successfully. Confirm that the content changes, and updated_at is newer.
 * 3. Attempt to update a non-existent comment (e.g., random UUID). Confirm appropriate error or not found response.
 * 4. Mark an existing comment as deleted by updating deleted_at. Confirm deleted_at is set.
 * 5. Attempt to update the content on a deleted comment. Confirm forbidden or logic error is triggered.
 */
export async function test_api_posts_test_update_comment_content_and_status(connection: api.IConnection) {
  // 1. Create comment dependency
  const comment = await api.functional.posts.comments.post(connection, {
    body: {
      user_id: typia.random<string & tags.Format<"uuid">>(),
      post_id: typia.random<string & tags.Format<"uuid">>(),
      content: RandomGenerator.paragraph()(),
    } satisfies IComment.ICreate,
  });
  typia.assert(comment);

  // 2. Update content
  const newContent = RandomGenerator.paragraph()();
  const updated = await api.functional.posts.comments.putById(connection, {
    id: comment.id,
    body: {
      content: newContent,
    } satisfies IComment.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("updated content")(newContent)(updated.content);
  TestValidator.predicate("updated_at is newer")(new Date(updated.updated_at) > new Date(comment.updated_at));

  // 3. Attempt to update non-existent comment
  await TestValidator.error("update non-existent comment should fail")(() =>
    api.functional.posts.comments.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        content: RandomGenerator.paragraph()(),
      } satisfies IComment.IUpdate,
    })
  );

  // 4. Soft-delete the comment
  const deletionTime = new Date().toISOString();
  const deleted = await api.functional.posts.comments.putById(connection, {
    id: comment.id,
    body: {
      deleted_at: deletionTime,
    } satisfies IComment.IUpdate,
  });
  typia.assert(deleted);
  TestValidator.equals("deleted_at set")(deletionTime)(deleted.deleted_at);

  // 5. Attempt to update deleted comment's content
  await TestValidator.error("update after delete forbidden")(() =>
    api.functional.posts.comments.putById(connection, {
      id: comment.id,
      body: {
        content: RandomGenerator.paragraph()(),
      } satisfies IComment.IUpdate,
    })
  );
}

