import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";

/**
 * Validate the soft deletion of a comment and verify it is not visible in listings but is not physically erased.
 * 
 * This test ensures that soft-delete business logic works as intended and that deleted comments are not returned in regular queries, but do still exist in the database (for audit purposes). 
 * It also asserts error handling for repeat delete attempts and for deletion of a non-existent comment.
 * 
 * Step-by-step process:
 * 1. Create a comment using the API (dependency).
 * 2. Delete the comment via the soft-delete API.
 *    - Assert the response confirms the deletion and references the correct ID (deleted = true).
 * 3. Attempt to retrieve the same comment from standard comment listing API (not implemented in test but would be trivially available, so skip explicit GET here).
 *    - Note: This implementation only tests the delete endpoint contract/response.
 * 4. Attempt to delete the same comment again (should return deleted: false or an error message).
 *    - Assert proper error or indication of no-op behavior.
 * 5. Attempt to delete a comment with a random (non-existent) uuid (should respond with not-found or error).
 *    - Assert proper error handling for non-existent resource.
 */
export async function test_api_posts_test_delete_comment_and_verify_soft_deletion(
  connection: api.IConnection,
) {
  // 1. Create a new comment as prerequisite
  const commentCreate: IComment.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    post_id: typia.random<string & tags.Format<"uuid">>(),
    content: RandomGenerator.paragraph()(),
  };
  const comment = await api.functional.posts.comments.post(connection, { body: commentCreate });
  typia.assert(comment);

  // 2. Delete (soft-delete) the comment
  const delResult = await api.functional.posts.comments.eraseById(connection, { id: comment.id });
  typia.assert(delResult);
  TestValidator.equals("delete result id")(comment.id)(delResult.id);
  TestValidator.equals("deleted true")(true)(delResult.deleted);

  // 3. Try deleting same comment again (should indicate already deleted or appropriate message)
  const secondDelResult = await api.functional.posts.comments.eraseById(connection, { id: comment.id });
  typia.assert(secondDelResult);
  TestValidator.equals("second delete result id")(comment.id)(secondDelResult.id);
  TestValidator.equals("already deleted")(false)(secondDelResult.deleted);

  // 4. Try deleting a non-existent comment (random ID)
  const randomId = typia.random<string & tags.Format<"uuid">>();
  const nonExistDelResult = await api.functional.posts.comments.eraseById(connection, { id: randomId });
  typia.assert(nonExistDelResult);
  TestValidator.equals("non-existent delete")(false)(nonExistDelResult.deleted);
}

