 * 다양한 필터와 페이지네이션 조합으로 votes 조회 API의 핵심 동작 및 엣지케이스 검증
 *
 * - 투표(user, post, comment별) 데이터 사전 생성 → 다양한 필터 및 조합조건에 대한 리스트 조회
 * - 페이징(offset/limit으로 쪼개기 및 마지막 empty)및 정렬 옵션(오름/내림차순) 일관성
 * - 존재하지 않는 id (user, post, comment)로 요청시 empty 정상 확인
 * - 모든 응답 구조는 typia.assert로, 결과 필터 정확성은 TestValidator.equals 등으로 확인
 *
 * 1. (준비) 2명 user, 2개 post, 2개 comment, 그리고 이 조합으로 여러 개의 투표 기록 생성
 * 2. userId 단독 필터: 해당 유저의 투표만 정확히 필터되는지
 * 3. postId 단독 필터: 해당 post 대상 투표만 정확히 필터되는지
 * 4. commentId 단독 필터: 해당 comment 대상 투표만 정확히 필터되는지
 * 5. userId+postId 조합: 그 교집합 데이터만 나오고 정확(개수/값)한지
 * 6. 페이징(offset/limit=1): 한 건씩 쪼개 여러 page 순차 요청, 마지막 page empty 확인
 * 7. 존재하지 않는 id(userId/postId/commentId)로 조회 시 empty 올바른지
 * 8. sort=created_at:desc와 asc로 각각 조회, 결과 역순 정렬 확인
 */
export async function test_api_votes_test_list_votes_with_varied_filters(
  connection: api.IConnection,
) {
  // --- 1. 준비: 여러 user/post/comment/vote 사전 생성 ---
  // user 두 명 실제로 생성(이 부분은 가정/mock/fake uuid 활용)
  const userA = typia.random<string & tags.Format<"uuid">>();
  const userB = typia.random<string & tags.Format<"uuid">>();
  // post, comment 두 개씩 id 할당
  const post1 = typia.random<string & tags.Format<"uuid">>();
  const post2 = typia.random<string & tags.Format<"uuid">>();
  const comment1 = typia.random<string & tags.Format<"uuid">>();
  const comment2 = typia.random<string & tags.Format<"uuid">>();
  // 실제 쿼리 대응 투표 여러개 조립
  const votes = [
    // userA가 post1에 +1, post2에 -1(duo)
    { user_id: userA, post_id: post1, comment_id: null, value: 1 },
    { user_id: userA, post_id: post2, comment_id: null, value: -1 },
    // userB가 post1에 +1, comment1에 +1
    { user_id: userB, post_id: post1, comment_id: null, value: 1 },
    { user_id: userB, post_id: null, comment_id: comment1, value: 1 },
    // userA가 comment2에 -1
    { user_id: userA, post_id: null, comment_id: comment2, value: -1 },
  ];
  // 실제 votes 테이블이 있다면 위 값들을 사전 등록해야 하고, 테스트 환경에서는 아래처럼 직접 fixture 투입한다고 가정
  // 즉 실제로는 votes create API 등을 통해 등록해야 함(여기선 fixture 가정)

  // --- 2. userId별 필터 ---
  let res = await api.functional.votes.votes.patch(connection, {
    body: { userId: userA },
  });
  typia.assert(res);
  TestValidator.equals("userA votes")(2 + 1)(res.data.length); // 2 post + 1 comment
  TestValidator.predicate("모든 user_id=userA")(res.data.every((v) => v.user_id === userA));

  // --- 3. postId별 필터 ---
  res = await api.functional.votes.votes.patch(connection, {
    body: { postId: post1 },
  });
  typia.assert(res);
  TestValidator.equals("post1 votes")(2)(res.data.length); // userA, userB
  TestValidator.predicate("모두 post_id=post1 && comment_id=null")(res.data.every((v) => v.post_id === post1 && (!v.comment_id || v.comment_id===null)));

  // --- 4. commentId별 필터 ---
  res = await api.functional.votes.votes.patch(connection, {
    body: { commentId: comment2 },
  });
  typia.assert(res);
  TestValidator.equals("comment2 votes")(1)(res.data.length);
  TestValidator.predicate("모두 comment_id=comment2 && post_id=null")(res.data.every((v) => v.comment_id === comment2 && (!v.post_id || v.post_id===null)));

  // --- 5. userId+postId 조합 필터 ---
  res = await api.functional.votes.votes.patch(connection, {
    body: { userId: userA, postId: post1 },
  });
  typia.assert(res);
  TestValidator.equals("userA+post1 votes")(1)(res.data.length);
  TestValidator.predicate("user_id, post_id 동시 일치")(res.data.every((v) => v.user_id === userA && v.post_id === post1));

  // --- 6. 페이징(offset/limit=1 & page 넘기기) ---
  // ① 첫번째 페이지(limit 1)
  res = await api.functional.votes.votes.patch(connection, {
    body: { userId: userA, limit: 1, offset: 0 },
  });
  typia.assert(res);
  TestValidator.equals("page1 len")(1)(res.data.length);
  // ② 두번째 페이지(offset 1)
  const totalA = 3;
  res = await api.functional.votes.votes.patch(connection, {
    body: { userId: userA, limit: 1, offset: 1 },
  });
  typia.assert(res);
  // ③ 마지막 offset(존재하지 않는 페이지)
  res = await api.functional.votes.votes.patch(connection, {
    body: { userId: userA, limit: 1, offset: totalA },
  });
  typia.assert(res);
  TestValidator.equals("빈 페이지 결과(존재X) empty")(0)(res.data.length);

  // --- 7. 존재하지 않는 id 필터 (빈 리스트)
  const nonExist = typia.random<string & tags.Format<"uuid">>();
  // userId
  res = await api.functional.votes.votes.patch(connection, {
    body: { userId: nonExist },
  });
  typia.assert(res);
  TestValidator.equals("not-found user")(0)(res.data.length);
  // postId
  res = await api.functional.votes.votes.patch(connection, {
    body: { postId: nonExist },
  });
  typia.assert(res);
  TestValidator.equals("not-found post")(0)(res.data.length);
  // commentId
  res = await api.functional.votes.votes.patch(connection, {
    body: { commentId: nonExist },
  });
  typia.assert(res);
  TestValidator.equals("not-found comment")(0)(res.data.length);

  // --- 8. sort 옵션 검증(desc/asc) ---
  // (userB가 post1, comment1에 투표하므로 이 중 created_at 기준 정렬을 가정)
  res = await api.functional.votes.votes.patch(connection, {
    body: { userId: userB, sort: "created_at:desc" },
  });
  typia.assert(res);
  const descIds = res.data.map((v) => v.id);
  res = await api.functional.votes.votes.patch(connection, {
    body: { userId: userB, sort: "created_at:asc" },
  });
  typia.assert(res);
  const ascIds = res.data.map((v) => v.id);
  TestValidator.equals("desc vs asc 역순")(descIds.slice().reverse())(ascIds);
}

