import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IVote";

/**
 * Test retrieving a vote's details by ID, including both successful retrieval and not found error scenario.
 *
 * Business context:
 * This test verifies the vote retrieval endpoint's correctness and robustness. It ensures that valid vote details are properly returned when queried by ID, and that attempts to retrieve non-existent votes correctly handle errors (typically resulting in a 404 or similar business logic error).
 *
 * Steps:
 * 1. Create a new vote (as precondition for retrieval).
 * 2. Retrieve the created vote by its ID. Validate that returned details match the created vote's data and schema.
 * 3. Attempt to fetch a vote using a random non-existent UUID. Confirm that an error is thrown (and that error type/code matches expected not found semantics).
 */
export async function test_api_votes_test_get_vote_details_success_and_not_found(
  connection: api.IConnection,
) {
  // 1. Create a new vote for setup
  const userId: string = typia.random<string & tags.Format<"uuid">>();
  const postId: string = typia.random<string & tags.Format<"uuid">>();
  const voteInput: IVote.ICreate = {
    user_id: userId,
    value: RandomGenerator.pick([1,-1]),
    post_id: postId,
    comment_id: null,
  };
  const created: IVote = await api.functional.votes.votes.post(connection, { body: voteInput });
  typia.assert(created);

  // 2. Retrieve the created vote by its ID
  const found: IVote = await api.functional.votes.votes.getById(connection, { id: created.id });
  typia.assert(found);
  TestValidator.equals("id")(created.id)(found.id);
  TestValidator.equals("user_id")(userId)(found.user_id);
  TestValidator.equals("post_id")(postId)(found.post_id);
  TestValidator.equals("value")(voteInput.value)(found.value);
  // Not checking comment_id since it's null by construction

  // 3. Try to fetch a non-existent vote
  const notFoundId: string = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("non-existent vote returns not found error")(
    async () => {
      await api.functional.votes.votes.getById(connection, { id: notFoundId });
    },
  );
}

