import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IVote";

/**
 * Test retrieving a vote's details by ID, including both success and not-found scenario.
 *
 * This test ensures the GET /votes/votes/{id} endpoint returns correct vote details when queried with a valid ID, and properly throws an error for a non-existent vote ID.
 *
 * Steps:
 * 1. Create a new vote (for retrieval).
 * 2. Retrieve the vote by its exact ID and check output integrity (all key fields).
 * 3. Attempt to fetch a vote using a random non-existent UUID, expecting error.
 */
export async function test_api_votes_test_get_vote_details_success_and_not_found(
  connection: api.IConnection,
) {
  // 1. Create a new vote for test setup
  const userId: string = typia.random<string & tags.Format<"uuid">>();
  const postId: string = typia.random<string & tags.Format<"uuid">>();
  const voteInput: IVote.ICreate = {
    user_id: userId,
    value: RandomGenerator.pick([1, -1]),
    post_id: postId,
    comment_id: null,
  };
  const created: IVote = await api.functional.votes.votes.post(connection, { body: voteInput });
  typia.assert(created);

  // 2. Retrieve the created vote by its ID and verify all major fields
  const found: IVote = await api.functional.votes.votes.getById(connection, { id: created.id });
  typia.assert(found);
  TestValidator.equals("vote id matches")(created.id)(found.id);
  TestValidator.equals("user_id matches")(userId)(found.user_id);
  TestValidator.equals("post_id matches")(postId)(found.post_id);
  TestValidator.equals("vote value matches")(voteInput.value)(found.value);
  // comment_id should be null (for this test)
  TestValidator.equals("comment_id is null")(null)(found.comment_id);

  // 3. Attempt to retrieve vote using a non-existent (random) id -- should error
  const notFoundId: string = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("Fetching non-existent vote throws error")(
    async () => {
      await api.functional.votes.votes.getById(connection, { id: notFoundId });
    },
  );
}

