import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IVote";

/**
 * Comprehensive test for creating a vote (upvote/downvote) in the voting system.
 *
 * This test validates the entire voting workflow:
 * - Successful vote creation with valid input
 * - Ensures one vote per user per content (uniqueness constraint)
 * - Checks validation for incomplete or invalid vote data
 *
 * Steps:
 * 1. Generate a registered user (as defined by the user_id uniqueness constraint).
 * 2. Assume the existence of a valid post or comment ID (simulate target for test).
 * 3. Create a valid upvote for a post (user_id + post_id + value = +1).
 * 4. Attempt to submit the same vote again with identical combination (should fail for uniqueness).
 * 5. Submit with missing required fields (e.g., omit value or both post_id and comment_id) to test validation error response.
 * 6. Submit vote on a comment with valid input (mutually exclusive with post_id).
 * 7. Attempt invalid combinations (both post_id and comment_id provided; both missing) and check for error.
 *
 * Throughout, assert correct IVote response structures or error handling (validation/uniqueness error). */
export async function test_api_votes_test_create_vote_with_validation_and_uniqueness_enforcement(connection: api.IConnection) {
  // 1. Generate a user
  const user_id: string = typia.random<string & tags.Format<"uuid">>();

  // 2. Simulate target IDs for post and comment
  const post_id: string = typia.random<string & tags.Format<"uuid">>();
  const comment_id: string = typia.random<string & tags.Format<"uuid">>();

  // 3. Create a valid upvote on a post
  const vote_post = await api.functional.votes.votes.post(connection, {
    body: {
      user_id,
      value: 1,
      post_id,
      comment_id: null,
    } satisfies IVote.ICreate,
  });
  typia.assert(vote_post);

  // 4. Attempt to submit the same vote again (should fail uniqueness)
  await TestValidator.error("duplicate vote by same user on same post should fail")(() =>
    api.functional.votes.votes.post(connection, {
      body: {
        user_id,
        value: 1,
        post_id,
        comment_id: null,
      } satisfies IVote.ICreate,
    })
  );

  // 5. Submit with missing value (should fail validation)
  await TestValidator.error("vote missing value should fail validation")(() =>
    api.functional.votes.votes.post(connection, {
      body: {
        user_id,
        // value missing
        post_id,
        comment_id: null,
      } as unknown as IVote.ICreate,
    })
  );

  // 5b. Submit with both post_id and comment_id missing (should fail validation)
  await TestValidator.error("vote missing target IDs should fail validation")(() =>
    api.functional.votes.votes.post(connection, {
      body: {
        user_id,
        value: -1,
        post_id: null,
        comment_id: null,
      } satisfies IVote.ICreate,
    })
  );

  // 6. Create a valid downvote on a comment
  const vote_comment = await api.functional.votes.votes.post(connection, {
    body: {
      user_id,
      value: -1,
      post_id: null,
      comment_id,
    } satisfies IVote.ICreate,
  });
  typia.assert(vote_comment);

  // 7a. Submit with both post_id and comment_id provided (should fail validation)
  await TestValidator.error("vote with both post_id and comment_id should fail")(() =>
    api.functional.votes.votes.post(connection, {
      body: {
        user_id,
        value: 1,
        post_id,
        comment_id,
      } satisfies IVote.ICreate,
    })
  );
}

