import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IVote";

/**
 * Validate editing a vote (success, failure, and immutability).
 *
 * This test ensures that a vote can be updated for its value, but not for immutable fields, and checks error handling when using invalid data or non-existent vote IDs.
 *
 * 1. Create a vote that can be edited in tests.
 * 2. Edit the value of the vote (e.g., change from +1 to -1). Verify the update.
 * 3. Attempt to update using an invalid vote value (e.g., 0, or a non-integer) and confirm error is thrown.
 * 4. Try to update a vote that does not exist and expect a not found or similar error.
 * 5. Attempt to edit an immutable field (such as user_id, post_id, comment_id) and verify that the operation is rejected.
 */
export async function test_api_votes_test_update_vote_success_failure_and_immutability(connection: api.IConnection) {
  // 1. Create a new vote for a post
  const user_id = typia.random<string & tags.Format<"uuid">>();
  const post_id = typia.random<string & tags.Format<"uuid">>();
  const createVoteBody: IVote.ICreate = {
    user_id,
    value: 1,
    post_id,
    comment_id: null,
  };
  const vote = await api.functional.votes.votes.post(connection, { body: createVoteBody });
  typia.assert(vote);
  // 2. Successfully edit the vote value
  const updatedVote = await api.functional.votes.votes.putById(connection, { id: vote.id, body: { value: -1 } });
  typia.assert(updatedVote);
  TestValidator.equals("vote.id should remain unchanged")(vote.id)(updatedVote.id);
  TestValidator.equals("vote.value should update")(-1)(updatedVote.value);
  // 3. Attempt to update using an invalid value (0)
  await TestValidator.error("should fail: value=0 not allowed")(async () => {
    await api.functional.votes.votes.putById(connection, {
      id: vote.id,
      body: { value: 0 },
    });
  });
  // 4. Attempt to update with a non-existent vote ID
  await TestValidator.error("should fail: non-existent vote ID")(async () => {
    await api.functional.votes.votes.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { value: 1 },
    });
  });
  // 5. Try to update immutable fields (simulate by attempting fake extra data - should be rejected)
  // Type safety prevents passing extra props, so this is naturally guarded at compile time.
  // If the API function allowed such attempts, we'd expect a failure.
}

