 * 1. Create a vote for a post (the dependency). This verifies initial insertion.
 * 2. Edit the value of the vote to change from +1 to -1. Ensure the update applies (id stays the same, value updates).
 * 3. Attempt to update the vote to an invalid value: 0 (should error).
 * 4. Attempt to update a non-existent vote ID (should error).
 * 5. Attempt to inject immutable property update (TS prevents; comment rationale).
 */
export async function test_api_votes_test_update_vote_success_failure_and_immutability(
  connection: api.IConnection,
) {
  // 1. Create a vote on a post (dependency from scenario)
  const user_id = typia.random<string & tags.Format<"uuid">>();
  const post_id = typia.random<string & tags.Format<"uuid">>();
  const createVoteBody: IVote.ICreate = {
    user_id,
    value: 1,
    post_id,
    comment_id: null,
  };
  const vote = await api.functional.votes.votes.post(connection, {
    body: createVoteBody,
  });
  typia.assert(vote);

  // 2. Edit the value: +1 -> -1
  const updatedVote = await api.functional.votes.votes.putById(connection, {
    id: vote.id,
    body: {
      value: -1,
    } satisfies IVote.IUpdate,
  });
  typia.assert(updatedVote);
  TestValidator.equals("id should remain the same")(vote.id)(updatedVote.id);
  TestValidator.equals("value updated correctly")(-1)(updatedVote.value);
  TestValidator.equals("user_id remains unchanged")(user_id)(updatedVote.user_id);
  TestValidator.equals("post_id remains unchanged")(post_id)(updatedVote.post_id);

  // 3. Try to update with an invalid value (should throw error, e.g., 0 not allowed)
  await TestValidator.error("reject invalid value 0")(async () => {
    await api.functional.votes.votes.putById(connection, {
      id: vote.id,
      body: {
        value: 0,
      } satisfies IVote.IUpdate,
    });
  });

  // 4. Try to update a non-existent vote ID (should throw error)
  await TestValidator.error("non-existent vote id should fail")(async () => {
    await api.functional.votes.votes.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        value: 1,
      } satisfies IVote.IUpdate,
    });
  });

  // 5. Immutable field edits are type-blocked by IVote.IUpdate; the API and type prevent attempt.
  // Documented for audit. Only mutable property is 'value'.
}

