import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IVote";

/**
 * Validate that deleting a vote works correctly and enforces removal.
 *
 * This test verifies two scenarios:
 * 1. Successfully deleting an existing vote (created beforehand), ensuring it is removed and no longer retrievable.
 * 2. Attempting to delete a non-existent vote (random UUID), expecting appropriate error behavior.
 *
 * Steps:
 * 1. Create a valid vote using the dependency API.
 * 2. Delete the vote via its ID using the eraseById endpoint.
 *    - Assert delete result indicates success and correct vote ID.
 * 3. Attempt to retrieve or delete the same vote again; expect error (e.g., not found).
 * 4. Attempt to delete a completely random, non-existent vote ID; expect error.
 */
export async function test_api_votes_test_delete_vote_and_confirm_removal(connection: api.IConnection) {
  // 1. Create a vote for the test
  const vote = await api.functional.votes.votes.post(connection, {
    body: {
      user_id: typia.random<string & tags.Format<"uuid">>(),
      value: 1,
      post_id: typia.random<string & tags.Format<"uuid">>(),
      comment_id: null
    } satisfies IVote.ICreate,
  });
  typia.assert(vote);

  // 2. Delete the vote
  const delResult = await api.functional.votes.votes.eraseById(connection, {
    id: vote.id,
  });
  typia.assert(delResult);
  TestValidator.equals("deleted vote id")(vote.id)(delResult.id);
  TestValidator.predicate("delete success")(delResult.deleted === true);

  // 3. Attempt to delete the same vote again (should fail)
  await TestValidator.error("deleting already deleted vote fails")(() =>
    api.functional.votes.votes.eraseById(connection, { id: vote.id }),
  );

  // 4. Attempt to delete a completely random, non-existent vote
  await TestValidator.error("deleting non-existent vote fails")(() =>
    api.functional.votes.votes.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    }),
  );
}

